nly store if i<j\n  function automatic integer pair_index(input [2:0] ia, input [2:0] ib);\n    integer i0, j0;\n    begin\n      if (ia < ib) begin\n        i0 = ia - 1;\n        j0 = ib - 1;\n      end else begin\n        i0 = ib - 1;\n        j0 = ia - 1;\n      end\n      pair_index = i0*6 + j0;\n    end\n  endfunction\n\n  // check if current partition (part_mask) is valid for year curY\n  function automatic bit partition_ok(\n      input [5:0] mask,\n      input [5:0] Y_local,\n      input [2:0] n_local,\n      input [6:0] edge_arr [0:35]\n  );\n    integer pi, pj;\n    integer pidx;\n    reg [2:0] cntA, cntB;\n    reg [2:0] limit;\n    reg inA_i, inA_j;\n    reg [5:0] yr;\n    begin\n      // only participants 0..n_local-1 are relevant\n      cntA = popcount6(mask & ((6'b000001 << n_local) - 1));\n      cntB = n_local - cntA;\n      limit = max_group_size(n_local);\n      if (cntA > limit || cntB > limit) begin\n        partition_ok = 1'b0;\n      end else begin\n        partition_ok = 1'b1;\n        for (pi = 0; pi < 6; pi = pi + 1) begin\n          if (pi < n_local) begin\n            for (pj = pi+1; pj < 6; pj = pj + 1) begin\n              if (pj < n_local) begin\n                pidx = pi*6 + pj;\n                if (edge_arr[pidx][6]) begin\n                  inA_i = mask[pi];\n                  inA_j = mask[pj];\n                  yr    = edge_arr[pidx][5:0];\n                  if (inA_i && inA_j) begin\n                    if (!(yr < Y_local)) begin\n                      partition_ok = 1'b0;\n                      disable inner_loops;\n                    end\n                  end else if (!inA_i && !inA_j) begin\n                    if (!(yr >= Y_local)) begin\n                      partition_ok = 1'b0;\n                      disable inner_loops;\n                    end\n                  end\n                end\n              end\n            end\n          end\n        end\n      end\n      inner_loops: ;\n    end\n  endfunction\n\n  // Sequent